class Logger:
    _logs = []

    def __init__(self):
        pass

    @classmethod
    def from_file(cls, path):
        with open(path, 'r') as f:
            for line in f:
                cls._logs.append(line.strip())
        return cls

    @staticmethod
    def is_level_valid(level):
        return level in ('INFO', 'WARN', 'ERROR')

    def add(self, level, message):
        entry = f'{level}: {message}'
        Logger._logs.append(entry)

# Test
Logger.from_file('logs.txt')
print(Logger._logs)
print(Logger.is_level_valid('WARN'))
print(Logger.is_level_valid('DEBUG'))

